import subprocess

def err(word):
    r=subprocess.run(["./executable", word], capture_output=True, text=True)
    return "subcommand" in r.stderr, (r.stderr.split("Did you mean")[1].split("?")[0] if "Did you mean" in r.stderr else "")

for w in ["hal","hil","hol","hep","heq","hez","hallo","hillo","hello","hell","hllo","helo","helx","helox"]:
    e, sug = err(w)
    print(f"{w:8} err={e} sug={sug}")

for w in ["bui","bwild","world","abcde","buid","buil","build"]:
    e, sug = err(w)
    print(f"{w:8} err={e} sug={sug}")

# Check that "world" no error, but "bwild" does error (distance closer to build? world distance 3 to build, bwild distance 2?)
# Let's compute leven distance to build for world vs bwild
def lev(a,b):
    n,m=len(a),len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1): dp[i][0]=i
    for j in range(m+1): dp[0][j]=j
    for i in range(1,n+1):
        for j in range(1,m+1):
            dp[i][j]=min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+(0 if a[i-1]==b[j-1] else 1))
    return dp[n][m]
for w in ["world","bwild","buid","buil","bui","build","test","foo"]:
    print(w, lev(w,"build"), lev(w,"help"))

