import subprocess, re

def svg(txt):
    r=subprocess.run(["./executable"], input=txt, capture_output=True, text=True)
    return r.stdout

def lines(txt):
    out=svg(txt)
    ls=re.findall(r'<line[^>]+>', out)
    return ls

