            # For normal text like "hi", "hello", "Bob", we render
            # Check if token is purely shape: if set(token) <= set('+-|.\' o*<>='), we might skip unless token contains letters
            if re.fullmatch(r'[o\*\#\+\-\|\.\']+', token) and not re.search(r'[A-Za-z0-9]', token):
