                has_line_for_row = any(f'y="{scale_coord(r*16+8, scale_f32)}"' in cl for cl in content_lines if '<line' in cl)
                if has_line_for_row:
                    # If we added line for this row, skip shape tokens
                    continue
                # else, render as text
                pass
            # Escape token
            esc = token.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
            x = scale_coord(start*8+2, scale_f32)
            y = scale_coord(r*16+12, scale_f32)
            # Handle special case for "Bob" etc inside rect: original positions may be centered? Our simple start*8+2 may not match original's centering.
