            content_lines.append(f'  <text x="{x}" y="{y}" >{esc}</text>')
    svg_parts = []
    svg_parts.append(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w_str}" height="{h_str}" class="svgbob">')
    svg_parts.append(f'  <style>{style}</style>')
    svg_parts.append(defs.rstrip())
    svg_parts.append(f'  <rect class="backdrop" x="0" y="0" width="{w_str}" height="{h_str}"></rect>')
    for cl in content_lines:
        if 'backdrop' in cl:
            continue
        svg_parts.append(cl)
    svg_parts.append('</svg>')
    return '\n'.join(svg_parts) + '\n'

